// ─── Helpers ─────────────────────────────────────────────────────────────────

interface MatchResult {
  index: number;
  value: string;
  groups: (string | undefined)[];
  namedGroups: Record<string, string> | null;
  start: number;
  end: number;
  groupIndices: ([number, number] | undefined)[];
}

function runRegex(pattern: string, flags: string, text: string): { matches: MatchResult[]; error: string | null } {
  if (!pattern) return { matches: [], error: null };
  try {
    const effectiveFlags = flags.includes('g') ? flags : flags + 'g';
    // Add 'd' flag for group indices if supported
    let re: RegExp;
    try {
      re = new RegExp(pattern, effectiveFlags + 'd');
    } catch {
      re = new RegExp(pattern, effectiveFlags);
    }

    const matches: MatchResult[] = [];
    let i = 0;
    for (const m of text.matchAll(re)) {
      const groups = Array.from({ length: m.length - 1 }, (_, k) => m[k + 1]);
      const namedGroups = m.groups ? { ...m.groups } : null;
      const rawIndices = (m as any).indices as ([number, number] | undefined)[] | undefined;
      const groupIndices: ([number, number] | undefined)[] = rawIndices
        ? Array.from({ length: m.length - 1 }, (_, k) => rawIndices[k + 1])
        : [];
      matches.push({
        index: i++,
        value: m[0],
        groups,
        namedGroups,
        start: m.index!,
        end: m.index! + m[0].length,
        groupIndices,
      });
    }
    return { matches, error: null };
  } catch (e: any) {
    return { matches: [], error: e.message };
  }
}

// Build highlighted ReactNode array from text + matches
function buildHighlight(text: string, matches: MatchResult[]): React.ReactNode[] {
  if (matches.length === 0) return [text];

  const nodes: React.ReactNode[] = [];
  let cursor = 0;

  for (const m of matches) {
    if (m.start > cursor) nodes.push(text.slice(cursor, m.start));

    const matchText = text.slice(m.start, m.end);

    // Build inner spans for groups (only if we have indices)
    if (m.groupIndices.length > 0) {
      const inner: React.ReactNode[] = [];
      let innerCursor = m.start;

      // Collect valid group intervals
      const intervals = m.groupIndices
        .map((gi, idx) => gi ? { ...gi, gIdx: idx } : null)
        .filter(Boolean) as { 0: number; 1: number; gIdx: number }[];

      // Sort by start
      intervals.sort((a, b) => a[0] - b[0]);

      for (const gi of intervals) {
        if (gi[0] > innerCursor) {
          inner.push(text.slice(innerCursor, gi[0]));
        }
        if (gi[0] < gi[1]) {
          const color = GROUP_COLORS[gi.gIdx % GROUP_COLORS.length];
          inner.push(
            <span
              key={`g${gi.gIdx}`}
              style={{
                background: color.bg,
                borderBottom: `2px solid ${color.border}`,
                borderRadius: 2,
              }}
            >
              {text.slice(gi[0], gi[1])}
            </span>
          );
        }
        innerCursor = gi[1];
      }

      if (innerCursor < m.end) inner.push(text.slice(innerCursor, m.end));

      nodes.push(
        <MatchHighlight key={m.start}>
          {inner}
        </MatchHighlight>
      );
    } else {
      nodes.push(<MatchHighlight key={m.start}>{matchText}</MatchHighlight>);
    }

    cursor = m.end;
  }

  if (cursor < text.length) nodes.push(text.slice(cursor));
  return nodes;
}

// ─── Component ───────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [pattern, setPattern] = useState('([\\w.+-]+)@([\\w-]+)\\.([\\w.]+)');
  const [flags, setFlags] = useState<Set<Flag>>(new Set(['g', 'i']));
  const [text, setText] = useState(
    'Contact us at hello@example.com or support@atlantis.dev for assistance.\nInvalid ones: @nouser.com, noatsign.org'
  );
  const [menuOpen, setMenuOpen] = useState(false);
  const [saveOpen, setSaveOpen] = useState(false);
  const [currentDoc, setCurrentDoc] = useState<{ id: string; name: string } | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  const handleSave = async (name: string) => {
    setSaveOpen(false);
    await saveDoc('regexlab', name, JSON.stringify({ pattern, flags: [...flags], text }));
    setCurrentDoc(null);
  };

  const handleUpdate = async () => {
    if (!currentDoc) return;
    setSaveOpen(false);
    await updateDoc(currentDoc.id, currentDoc.name, JSON.stringify({ pattern, flags: [...flags], text }));
  };

  const handleLoad = (content: string, docId?: string, docName?: string) => {
    setCurrentDoc(docId && docName ? { id: docId, name: docName } : null);
    try {
      const { pattern: p, flags: f, text: t } = JSON.parse(content);
      if (p !== undefined) setPattern(p);
      if (f !== undefined) setFlags(new Set(f));
      if (t !== undefined) setText(t);
    } catch { /* ignore malformed saves */ }
  };

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const flagStr = Array.from(flags).join('');
  const { matches, error } = useMemo(() => runRegex(pattern, flagStr, text), [pattern, flagStr, text]);
  const highlighted = useMemo(() => buildHighlight(text, matches), [text, matches]);

  const toggleFlag = (f: Flag) => {
    setFlags((prev) => {
      const next = new Set(prev);
      if (next.has(f)) next.delete(f);
      else next.add(f);
      return next;
    });
  };

  const loadExample = (ex: typeof EXAMPLES[0]) => {
    setPattern(ex.pattern);
    setFlags(new Set(ex.flags.split('') as Flag[]));
    setText(ex.text);
    setMenuOpen(false);
  };

  const groupNames = useMemo(() => {
    if (!pattern) return [];
    const re = /\(\?<([^>]+)>/g;
    const names: string[] = [];
    let m: RegExpExecArray | null;
    while ((m = re.exec(pattern)) !== null) names.push(m[1]);
    return names;
  }, [pattern]);

  return (
    <Wrapper>
      <TopBar>
        <AtlantisLogo onClick={() => { window.location.hash = '#/home'; }} title="Home">
          Atl<span>antis</span>
        </AtlantisLogo>
        <TitleSep>/</TitleSep>
        <AppTitle>
          Regex Lab
          <AppTitleSub>live match</AppTitleSub>
        </AppTitle>
        <Spacer />
        <DocumentsMenu appId="regexlab" onLoad={handleLoad} />
        <SaveBtn onClick={() => setSaveOpen(true)}><Save size={14} />Save</SaveBtn>
        <DropdownWrapper ref={menuRef}>
          <DropdownBtn onClick={() => setMenuOpen((o) => !o)}>
            Examples <ChevronDown size={12} />
          </DropdownBtn>
          {menuOpen && (
            <DropdownMenu>
              {EXAMPLES.map((ex) => (
                <DropdownItem key={ex.label} onClick={() => loadExample(ex)}>
                  {ex.label}
                </DropdownItem>
              ))}
            </DropdownMenu>
          )}
        </DropdownWrapper>
        {topBarRight}
      </TopBar>
      {saveOpen && <SaveDialog onSave={handleSave} onUpdate={handleUpdate} existingDoc={currentDoc ?? undefined} onCancel={() => setSaveOpen(false)} />}

      <Body>
        {/* Pattern input */}
        <PatternRow>
          <Delimiter>/</Delimiter>
          <PatternInput
            hasError={!!error}
            value={pattern}
            onChange={(e) => setPattern(e.target.value)}
            placeholder="enter regex pattern…"
            spellCheck={false}
          />
          <Delimiter>/</Delimiter>
          {ALL_FLAGS.map((f) => (
            <FlagButton key={f} active={flags.has(f)} onClick={() => toggleFlag(f)} title={f}>
              {f}
            </FlagButton>
          ))}
          <StatusBadge ok={!error}>
            {error ? (
              <><AlertCircle size={13} /> {error}</>
            ) : pattern ? (
              <><CheckCircle size={13} /> {matches.length} match{matches.length !== 1 ? 'es' : ''}</>
            ) : null}
          </StatusBadge>
        </PatternRow>

        {/* Main editor + highlight */}
        <MainArea>
          <Pane>
            <PaneLabel>Test string</PaneLabel>
            <TextArea
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Paste or type your test string here…"
              spellCheck={false}
            />
          </Pane>
          <Pane>
            <PaneLabel>Highlighted matches</PaneLabel>
            <HighlightPane>{highlighted}</HighlightPane>
          </Pane>
        </MainArea>

        {/* Matches list */}
        <BottomPanel>
          <MatchesHeader>
            <MatchCount>{matches.length} match{matches.length !== 1 ? 'es' : ''}</MatchCount>
            {groupNames.length > 0 && (
              <span>
                Groups:{' '}
                {groupNames.map((name, i) => (
                  <GroupLabel key={name} colorIndex={i}> {name}</GroupLabel>
                ))}
              </span>
            )}
          </MatchesHeader>
          <MatchList>
            {matches.slice(0, 200).map((m) => (
              <MatchItem key={m.index}>
                <MatchIndex>#{m.index + 1}</MatchIndex>
                <MatchValue>{m.value}</MatchValue>
                {m.groups.map((g, gi) => {
                  if (g === undefined) return null;
                  const name = groupNames[gi] ?? `$${gi + 1}`;
                  return (
                    <React.Fragment key={gi}>
                      <GroupLabel colorIndex={gi}>{name}:</GroupLabel>
                      <GroupTag colorIndex={gi}>{g}</GroupTag>
                    </React.Fragment>
                  );
                })}
              </MatchItem>
            ))}
            {matches.length > 200 && (
              <MatchItem>
                <MatchIndex>…</MatchIndex>
                <span style={{ color: theme.colors.mainTextMuted }}>
                  {matches.length - 200} more matches not shown
                </span>
              </MatchItem>
            )}
          </MatchList>
        </BottomPanel>
      </Body>
    </Wrapper>
  );
}
